import * as T from './vendor/three.module.js';
export function createScene(host,onSelect){
 let renderer;try{renderer=new T.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'})}catch{host.innerHTML='<div class="webgl-fallback">3D is unavailable on this device.<br>Select any panel in the inspection map below.</div>';return{update(){},reset(){},setMode(){}}}
 renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0,0);host.appendChild(renderer.domElement);renderer.domElement.setAttribute('aria-label','Interactive 3D spacecraft. Drag to rotate; select panels using the map below.');
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(36,1,.1,100);camera.position.set(7,5,8);camera.lookAt(0,0,0);scene.add(new T.AmbientLight(0x8c9dac,2));const light=new T.DirectionalLight(0xf1f0e9,5);light.position.set(1,5,4);scene.add(light);const rim=new T.DirectionalLight(0xff632a,3);rim.position.set(-5,-1,-2);scene.add(rim);const blue=new T.DirectionalLight(0x718bdb,3);blue.position.set(2,0,-5);scene.add(blue);
 const station=new T.Group();scene.add(station);station.rotation.set(.04,.05,-.26);const panels=[],robots=[];let state,selected=11,mode='structure';
 const mat=(color,metalness=.8,roughness=.32)=>new T.MeshStandardMaterial({color,metalness,roughness});const metal=mat(0x7b8188),dark=mat(0x13191f),edge=mat(0xb8bdc6),gold=mat(0x846542);
 function mesh(g,m,parent=station){const o=new T.Mesh(g,m);parent.add(o);return o}
 const core=mesh(new T.CylinderGeometry(1.17,1.17,5.9,32),dark);core.rotation.z=Math.PI/2;
 for(let col=0;col<8;col++)for(let row=0;row<4;row++){const i=row*8+col,theta=row*Math.PI/2;const g=new T.BoxGeometry(.64,1.57,.11),p=mesh(g,metal.clone());p.position.set((col-3.5)*.7,Math.sin(theta)*1.2,Math.cos(theta)*1.2);p.rotation.x=-theta;p.userData.panel=i;panels[i]=p;const e=new T.LineSegments(new T.EdgesGeometry(g),new T.LineBasicMaterial({color:0x899199,transparent:true,opacity:.35}));p.add(e);for(const x of [-.25,.25])for(const y of [-.65,.65]){const bolt=mesh(new T.CylinderGeometry(.025,.025,.024,8),edge,p);bolt.rotation.x=Math.PI/2;bolt.position.set(x,y,.066)}}
 for(const x of [-3,-2.9,2.9,3]){const ring=mesh(new T.TorusGeometry(1.26,.08,10,48),edge);ring.rotation.y=Math.PI/2;ring.position.x=x}
 for(const x of [-3.05,3.05]){const cap=mesh(new T.CylinderGeometry(.92,1.23,.27,32),metal);cap.rotation.z=x<0?Math.PI/2:-Math.PI/2;cap.position.x=x;const port=mesh(new T.CylinderGeometry(.48,.48,.34,32),dark);port.rotation.z=Math.PI/2;port.position.x=x*1.07;const collar=mesh(new T.TorusGeometry(.48,.055,8,32),gold);collar.rotation.y=Math.PI/2;collar.position.x=x*1.13}
 for(const side of [-1,1]){const spar=mesh(new T.BoxGeometry(.13,2.7,.13),edge);spar.position.set(-.35,side*2.25,0);const solar=new T.Group;station.add(solar);solar.position.set(-.35,side*3.3,0);for(let i=0;i<4;i++)for(let j=0;j<3;j++){const cell=mesh(new T.BoxGeometry(.47,.61,.035),mat(0x152947,.65,.4),solar);cell.position.set((i-1.5)*.5,(j-1)*.64,0);const wire=new T.LineSegments(new T.EdgesGeometry(cell.geometry),new T.LineBasicMaterial({color:0x657b9c}));cell.add(wire)}}
 for(let k=0;k<2;k++){const group=new T.Group();station.add(group);mesh(new T.BoxGeometry(.27,.24,.2),mat(k?0xb9d5df:0xff632a,.5,.3),group);for(const x of [-.16,.16])for(const y of [-.14,.14]){const leg=mesh(new T.SphereGeometry(.06,8,8),dark,group);leg.position.set(x,y,-.1)}const eye=mesh(new T.SphereGeometry(.045,12,12),new T.MeshBasicMaterial({color:0x75efd7}),group);eye.position.z=.12;robots.push(group)}
 const halo=new T.Mesh(new T.TorusGeometry(.19,.01,8,32),new T.MeshBasicMaterial({color:0xff632a}));station.add(halo);
 const starGeo=new T.BufferGeometry;const coords=[];for(let i=0;i<220;i++){const a=i*137.5;coords.push(Math.sin(a)*20,Math.cos(a*1.2)*13,-9-Math.abs(Math.sin(a*2))*10)}starGeo.setAttribute('position',new T.Float32BufferAttribute(coords,3));scene.add(new T.Points(starGeo,new T.PointsMaterial({color:0x738296,size:.025,transparent:true,opacity:.5})));
 const ray=new T.Raycaster,pointer=new T.Vector2;let drag=null,moved=false;
 host.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY};moved=false;host.setPointerCapture(e.pointerId)});host.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;station.rotation.y+=dx*.007;station.rotation.x+=dy*.005;drag={x:e.clientX,y:e.clientY}});host.addEventListener('pointerup',e=>{drag=null;if(moved)return;const rect=host.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(panels,false)[0];if(hit)onSelect(hit.object.userData.panel)});
 const resize=()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();camera.position.set(w/h<1.2?10:7,w/h<1.2?7:5,w/h<1.2?12:8);camera.lookAt(0,0,0)};new ResizeObserver(resize).observe(host);resize();let frame=0;
 function animate(){requestAnimationFrame(animate);if(document.hidden)return;frame++;if(state){panels.forEach((p,i)=>{const b=state.policy.beliefs[i],seen=state.policy.obs[i].length;let color=mode==='risk'?(seen?new T.Color().lerpColors(new T.Color(0x254d4a),new T.Color(0xff5223),b.risk):new T.Color(0x29313c)):new T.Color(i===selected?0xd9b592:0x818a96);p.material.color.copy(color);p.material.emissive.setHex(i===selected?0x3a170a:0);p.material.wireframe=mode==='wire'});robots.forEach((r,i)=>{const rb=state.robots[i],p=panels[rb.panel],v=p.position.clone();v.y*=1.2;v.z*=1.2;r.position.lerp(v,.12);r.rotation.copy(p.rotation);r.visible=rb.online});const p=panels[state.latest?.panel??selected];halo.position.copy(p.position).multiply(new T.Vector3(1,1.11,1.11));halo.rotation.copy(p.rotation);halo.scale.setScalar(1+Math.sin(frame*.04)*.18)}renderer.render(scene,camera)}animate();return{update(s,i){state=s;selected=i},setMode(m){mode=m},reset(){station.rotation.set(.04,.05,-.26)}};
}
